async def cancel(self, name):
    record = self._records[name]
    supervisor = self._supervisors.get(name)
    if supervisor is None or supervisor.done():
        return
    # The supervisor owns the current attempt: cancelling it forwards the
    # cancellation to whatever it is awaiting, either the live attempt
    # task or the retry gate.
    supervisor.cancel()
    try:
        await supervisor
    except asyncio.CancelledError as error:
        if not supervisor.cancelled():
            raise
        if record.state == JobState.QUEUED:
            record.error = error
            record.state = JobState.CANCELLED

async def wait(self, name):
    supervisor = self._supervisors[name]
    try:
        await supervisor
    except asyncio.CancelledError:
        if not supervisor.cancelled():
            raise
    return self._records[name]
